SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL VE BEŞERÎ ÇEVRE UNSURLARI</text>\n  <rect x="35" y="60" width="305" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Doğal Çevre (İnsan Eli Değmeyen)</text>\n  <text x="60" y="120" font-size="12" fill="#334155">• Dağlar, platolar ve ovalar</text>\n  <text x="60" y="145" font-size="12" fill="#334155">• Nehirler, göller ve denizler</text>\n  <text x="60" y="170" font-size="12" fill="#334155">• Ormanlar ve doğal bitki örtüsü</text>\n  <text x="60" y="195" font-size="12" fill="#334155">• İklim koşulları ve yeraltı suları</text>\n  <rect x="360" y="60" width="305" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Beşerî Çevre (İnsan Eseri Olan)</text>\n  <text x="385" y="120" font-size="12" fill="#334155">• Yollar, köprüler ve tüneller</text>\n  <text x="385" y="145" font-size="12" fill="#334155">• Barajlar ve sulama kanalları</text>\n  <text x="385" y="170" font-size="12" fill="#334155">• Şehirler, konutlar ve fabrikalar</text>\n  <text x="385" y="195" font-size="12" fill="#334155">• Parklar, limanlar ve tarlalar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVREDEKİ DEĞİŞİMİN NEDENLERİ VE SONUÇLARI</text>\n  <rect x="40" y="60" width="290" height="175" rx="8" fill="#fefce8" stroke="#ca8a04"/>\n  <text x="185" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Değişimin Nedenleri</text>\n  <text x="60" y="115" font-size="11.5" fill="#334155">• Hızlı nüfus artışı ve göçler</text>\n  <text x="60" y="140" font-size="11.5" fill="#334155">• Sanayileşme ve fabrika yapımı</text>\n  <text x="60" y="165" font-size="11.5" fill="#334155">• Ulaşım ağlarının genişlemesi</text>\n  <text x="60" y="190" font-size="11.5" fill="#334155">• Yeni yerleşim alanları ihtiyacı</text>\n  <text x="185" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">İnsan ihtiyaçları değişimi tetikler</text>\n  <rect x="370" y="60" width="290" height="175" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="515" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Değişimin Sonuçları</text>\n  <text x="390" y="115" font-size="11.5" fill="#334155">• Tarım ve orman arazilerinin daralması</text>\n  <text x="390" y="140" font-size="11.5" fill="#334155">• Şehirleşme ve altyapı gelişimi</text>\n  <text x="390" y="165" font-size="11.5" fill="#334155">• Hava, su ve toprak kirliliği riski</text>\n  <text x="390" y="190" font-size="11.5" fill="#334155">• Yaşam konforunun artması</text>\n  <text x="515" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Denge gözetilerek kalkınma şarttır</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜRDÜRÜLEBİLİR ÇEVRE VE SORUMLU VATANDAŞLIK</text>\n  <rect x="40" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="135" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğayı Korumak</text>\n  <text x="135" y="115" text-anchor="middle" font-size="11" fill="#334155">Ağaçlandırma yapmak,</text>\n  <text x="135" y="135" text-anchor="middle" font-size="11" fill="#334155">yeşil alanları korumak,</text>\n  <text x="135" y="160" text-anchor="middle" font-size="11" fill="#334155">su kaynaklarını israf</text>\n  <text x="135" y="180" text-anchor="middle" font-size="11" fill="#334155">etmeden tüketmek.</text>\n  <text x="135" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Geleceğe Miras</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Planlı Şehirleşme</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11" fill="#334155">Verimli tarım alanlarına</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11" fill="#334155">bina yapmamak,</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">afetlere dayanıklı</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#334155">yapılar inşa etmek.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Güvenli Yaşam</text>\n  <rect x="470" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="565" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Geri Dönüşüm</text>\n  <text x="565" y="115" text-anchor="middle" font-size="11" fill="#334155">Atıkları ayrıştırmak,</text>\n  <text x="565" y="135" text-anchor="middle" font-size="11" fill="#334155">yenilenebilir enerji</text>\n  <text x="565" y="160" text-anchor="middle" font-size="11" fill="#334155">kaynaklarını tercih</text>\n  <text x="565" y="180" text-anchor="middle" font-size="11" fill="#334155">ederek havayı korumak.</text>\n  <text x="565" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Temiz Çevre</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
